import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            b[i] = sc.nextInt();
        }

        run(n, a, b);
        sc.close();
    }

    public static void run(int n, int[] a, int[] b) {
        int totalWin = 0;
        int[] bExtended = new int[n + 1];
        System.arraycopy(b, 0, bExtended, 0, n);
        bExtended[n] = b[0];

        for (int i = 0; i < 3; i++) {
            totalWin += Math.min(a[i], bExtended[i + 1]);
        }

        int[] bModified = new int[n];
        System.arraycopy(b, 0, bModified, 0, n);
        bModified[0] = b[2];

        for (int i = 0; i < 3; i++) {
            if (a[i] > 0) {
                int d = Math.min(a[i], bModified[i]);
                a[i] -= d;
                bModified[i] -= d;
                if (a[i] > 0) {
                    int nextIndex = (i + 1) % 3;
                    int d2 = Math.min(a[i], bModified[nextIndex]);
                    a[i] -= d2;
                    bModified[nextIndex] -= d2;
                }
            }
        }

        System.out.println(a[0] + a[1] + a[2] + " " + totalWin);
    }
}
